steps.checkScript:
need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
t=$(mktemp -d); trap 'rm -rf "$t"' EXIT

need clean_dir.sh build_dirs.sh
cp clean_dir.sh build_dirs.sh "$t"/
n=q$RANDOM
( cd "$t" && timeout 5 bash ./build_dirs.sh "$n" && touch keep.txt && timeout 5 bash ./clean_dir.sh "$n" ) >/dev/null 2>&1
[ -e "$t/$n" ] && { echo "Nach './clean_dir.sh $n' gibt es den Ordner $n noch."; exit 1; }
[ -f "$t/keep.txt" ] || { echo "clean_dir.sh hat zu viel gelöscht!"; exit 1; }
