need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
t=$(mktemp -d); trap 'rm -rf "$t"' EXIT

need makescript.sh
cp makescript.sh "$t"/
n=s$RANDOM
( cd "$t" && timeout 5 bash ./makescript.sh "$n" ) >/dev/null 2>&1
f="$t/$n.sh"
[ -f "$f" ] || { echo "'./makescript.sh $n' hat keine Datei $n.sh angelegt."; exit 1; }
head -n1 "$f" | grep -Eq '^#!/(usr/)?bin/(env )?(ba)?sh' || { echo "Die erste Zeile von $n.sh ist keine Shebang-Zeile."; exit 1; }
[ -x "$f" ] || { echo "$n.sh ist nicht ausführbar."; exit 1; }
out=$(cd "$t" && timeout 5 "./$n.sh" 2>&1)
[ "$out" = "$n Skript" ] || { echo "./$n.sh soll '$n Skript' ausgeben, war: $out"; exit 1; }
echo "Generator funktioniert!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
t=$(mktemp -d); trap 'rm -rf "$t"' EXIT

need dated_copy1.sh
