[ -f "$f" ] || { echo "Nach './dated_copy1.sh notiz.txt' fehlt die Datei $f."; exit 1; }
cmp -s notiz.txt "$f" || { echo "$f hat nicht denselben Inhalt wie das Original."; exit 1; }
