need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need werkstatt.sh
want=$(( $(grep Werkstatt klassenkassa.csv | cut -d, -f3 | paste -sd+) ))
out=$(timeout 5 bash werkstatt.sh 2>&1)
echo "$out" | grep -Eq "(^|[^0-9])$want([^0-9]|$)" || { echo "Die Summe stimmt nicht. Ausgabe: $out"; exit 1; }
grep -q "$want" werkstatt.sh && { echo "Das Ergebnis darf nicht fest im Skript stehen."; exit 1; }
grep -q paste werkstatt.sh || { echo "Verwende paste, um den Ausdruck zu bauen."; exit 1; }
