need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
need random.sh
chk() {
  lo=$1; hi=$2; seen=""
  for i in $(seq 1 60); do
    n=$(timeout 5 bash random.sh $lo $hi 2>&1 | tail -n1)
    [[ "$n" =~ ^-?[0-9]+$ ]] && [ "$n" -ge $lo ] && [ "$n" -le $hi ] || { echo "'./random.sh $lo $hi' lieferte '$n' – nicht im Bereich $lo bis $hi."; exit 1; }
    seen="$seen $n"
  done
  echo "$seen"
}
s=$(chk 1 3) || { echo "$s"; exit 1; }
for v in 1 2 3; do echo " $s " | grep -q " $v " || { echo "'./random.sh 1 3' liefert nie $v – sind die Grenzen inklusive?"; exit 1; }; done
s=$(chk 10 45) || { echo "$s"; exit 1; }
[ "$(timeout 5 bash random.sh 7 7 | tail -n1)" = 7 ] || { echo "'./random.sh 7 7' soll 7 liefern."; exit 1; }
echo "Zufall im Griff!"

