t=$(mktemp -d); trap 'rm -rf "$t"' EXIT

need groesse.sh
head -c 101 /dev/zero > "$t/g"; head -c 100 /dev/zero > "$t/k"
timeout 5 bash groesse.sh "$t/g" 2>&1 | grep -q 'Datei ist zu groß' || { echo "Bei 101 Bytes soll 'Datei ist zu groß' kommen."; exit 1; }
timeout 5 bash groesse.sh gross.txt 2>&1 | grep -q 'Datei ist zu groß' || { echo "Bei gross.txt soll 'Datei ist zu groß' kommen."; exit 1; }
timeout 5 bash groesse.sh "$t/k" 2>&1 | grep -q 'zu groß' && { echo "Bei genau 100 Bytes ist die Datei nicht zu groß."; exit 1; }
echo "Größe erkannt!"

