need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
t=$(mktemp -d); trap 'rm -rf "$t"' EXIT

need makedir.sh
cp makedir.sh "$t"/; cd "$t"
n=x$RANDOM
echo n | timeout 5 bash ./makedir.sh $n >/dev/null 2>&1
[ -d $n ] && [ "$(cat $n/$n.txt 2>/dev/null)" = "$n" ] || { echo "'./makedir.sh $n' soll $n/$n.txt mit Inhalt $n anlegen."; exit 1; }
