out=$(echo n | timeout 5 bash ./makedir.sh $n 2>&1)
echo "$out" | grep -q 4 || { echo "Die Frage soll die Anzahl der Files (hier 4) nennen. Ausgabe: $out"; exit 1; }
[ -f $n/a ] || { echo "Bei Antwort n darf nichts gelöscht werden."; exit 1; }
echo j | timeout 5 bash ./makedir.sh $n >/dev/null 2>&1
[ ! -e $n/a ] && [ "$(cat $n/$n.txt 2>/dev/null)" = "$n" ] || { echo "Bei Antwort j soll das Verzeichnis gelöscht und neu (nur mit $n.txt) angelegt werden."; exit 1; }
