t=$(mktemp -d); trap 'rm -rf "$t"' EXIT

need number.sh
cp number.sh "$t"/; cd "$t"
printf 'bbb eins\nccc zwei\naaa drei\n' > test.txt
out=$(timeout 5 bash ./number.sh test.txt 2>&1)
