need primzahlen.sh prim.sh
grep -q 'prim.sh' primzahlen.sh || { echo "primzahlen.sh soll prim.sh aufrufen."; exit 1; }
out=$(timeout 25 bash primzahlen.sh 2>&1 | tail -n1)
