need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
t=$(mktemp -d); trap 'rm -rf "$t"' EXIT

need lsx.sh
mkdir -p "$t/d/sub1" "$t/d/sub2"
s=$((RANDOM%900+100)); head -c $s /dev/zero > "$t/d/datei.bin"; head -c 7 /dev/zero > "$t/d/klein.txt"
touch "$t/d/sub1/a" "$t/d/sub1/b" "$t/d/sub1/c"
out=$(timeout 5 bash lsx.sh "$t/d" 2>&1)
line() { echo "$out" | grep -F "$1" | head -n1; }
for e in "datei.bin:$s" "klein.txt:7" "sub1:3" "sub2:0"; do
  name=${e%%:*}; n=${e##*:}
  l=$(line "$name")
  [ -n "$l" ] || { echo "Der Eintrag $name fehlt. Ausgabe:"; echo "$out"; exit 1; }
  echo "${l#*$name}" | grep -Eq "(^|[^0-9])$n([^0-9]|$)" || { echo "Bei $name soll $n stehen. Zeile: $l"; exit 1; }
done
[ -z "$(timeout 5 bash lsx.sh "$t/gibtsnicht" 2>&1)" ] || { echo "Bei einem nicht existierenden Verzeichnis soll nichts ausgegeben werden."; exit 1; }
echo "ls on steroids!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
t=$(mktemp -d); trap 'rm -rf "$t"' EXIT

need adduser.sh
grep -Eq '^[[:space:]]*(function[[:space:]]+)?passwd[[:space:]]*\(\)' adduser.sh || { echo "In adduser.sh fehlt die Funktion passwd()."; exit 1; }
grep -v '^[[:space:]]*#' adduser.sh | grep -Eq '(^|[^a-z_.])(useradd|adduser)[[:space:]]' && { echo "useradd/adduser darf nicht verwendet werden."; exit 1; }
cp -a sysroot adduser.sh "$t"/; cd "$t"
max=$(awk -F: '$3>=1000 && $3<60000 {print $3}' sysroot/etc/passwd | sort -n | tail -n1)
a=anna$RANDOM; b=bert$RANDOM
printf 'j\nj\nj\nj\n' | timeout 5 bash ./adduser.sh $a $b >/dev/null 2>&1
for u in $a $b; do
  l=$(grep "^$u:" sysroot/etc/passwd)
  [ -n "$l" ] || { echo "$u fehlt in sysroot/etc/passwd."; exit 1; }
  echo "$l" | grep -Eq "^$u:x:[0-9]+:[0-9]+:[^:]*:/home/$u:/bin/bash$" || { echo "Die Zeile für $u hat nicht das Format name:x:UID:GID:,,,:/home/name:/bin/bash – $l"; exit 1; }
  uid=$(echo "$l" | cut -d: -f3); gid=$(echo "$l" | cut -d: -f4)
  [ "$uid" -gt "$max" ] && [ "$uid" = "$gid" ] || { echo "UID/GID von $u muss größer als die bisher größte ($max) und gleich sein: $l"; exit 1; }
  [ -d sysroot/home/$u ] || { echo "Das Home-Verzeichnis sysroot/home/$u fehlt."; exit 1; }
  [ "$(stat -c %a sysroot/home/$u | cut -c2-)" = "00" ] || { echo "Andere dürfen keinen Zugriff auf sysroot/home/$u haben (Rechte: $(stat -c %a sysroot/home/$u))."; exit 1; }
done
[ "$(cut -d: -f3 sysroot/etc/passwd | sort | uniq -d)" = "" ] || { echo "Eine UID kommt doppelt vor."; exit 1; }
echo "Benutzer angelegt!"

need() { for f in "$@"; do [ -f "$f" ] || { echo "$f gibt es noch nicht."; exit 1; }; done; }
t=$(mktemp -d); trap 'rm -rf "$t"' EXIT

need adduser.sh
grep -Eq '^[[:space:]]*(function[[:space:]]+)?shadow[[:space:]]*\(\)' adduser.sh || { echo "In adduser.sh fehlt die Funktion shadow()."; exit 1; }
cp -a sysroot adduser.sh "$t"/; cd "$t"
a=anna$RANDOM; b=bert$RANDOM
printf 'j\nn\ngeheim123\n' | timeout 5 bash ./adduser.sh $a $b >/dev/null 2>&1
chk() {
  l=$(grep "^$1:" sysroot/etc/shadow)
  [ -n "$l" ] || { echo "$1 fehlt in sysroot/etc/shadow."; exit 1; }
  h=$(echo "$l" | cut -d: -f2)
  salt=$(echo "$h" | cut -d'$' -f3)
  case "$h" in '$6$'*|'$5$'*|'$1$'*) ;; *) echo "Das Passwortfeld von $1 ist kein Hash ($h)."; exit 1;; esac
  alg=$(echo "$h" | cut -d'$' -f2)
  [ "$(openssl passwd -$alg -salt "$salt" "$2")" = "$h" ] || { echo "Das Passwort von $1 sollte '$2' sein."; exit 1; }
  [ "$(echo "$l" | awk -F: '{print NF}')" = 9 ] || { echo "Die shadow-Zeile von $1 braucht 9 Felder (name:HASH:19000:0:99999:7:::)."; exit 1; }
}
chk $a $a
chk $b geheim123
grep -q "^root:" sysroot/etc/shadow || { echo "Die bestehenden Einträge in shadow dürfen nicht verloren gehen."; exit 1; }
echo "Passwörter gesetzt!"
